import { useState } from 'react';
import type { ExportFormat } from '../../../../src/shared/contract';
import { downloadFile, type Transport } from '../transport';

const FORMATS: Array<[ExportFormat, string]> = [
  ['csv', 'CSV'],
  ['markdown', 'Summary (.md)'],
  ['html', 'Summary (.html)'],
];

/** One-click exports. Files are generated by the resolver and downloaded in the browser (no egress). */
export function ExportBar({ transport, issueKey, timezone }: { transport: Transport; issueKey: string; timezone: string | null }) {
  const [busy, setBusy] = useState<ExportFormat | null>(null);
  const [error, setError] = useState<string | null>(null);

  const run = async (format: ExportFormat) => {
    setBusy(format);
    setError(null);
    try {
      const res = await transport.invoke('exportRollup', { issueKey, format, timezone });
      if (!res.ok) setError(res.error.message);
      else downloadFile(res.data);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setBusy(null);
    }
  };

  return (
    <div className="export-bar" role="group" aria-label="Export">
      {FORMATS.map(([format, label]) => (
        <button key={format} type="button" className="btn" onClick={() => run(format)} disabled={busy !== null}>
          {busy === format ? 'Exporting…' : `Export ${label}`}
        </button>
      ))}
      {error && (
        <span className="inline-error" role="alert">
          {error}
        </span>
      )}
    </div>
  );
}
